META = dict(
    outline='ಶ್ಲೋಕಗಳು 1–12: ಸಂನ್ಯಾಸ ಮತ್ತು ತ್ಯಾಗ: ಕರ್ಮವನ್ನಲ್ಲ, ಫಲದ ಆಸಕ್ತಿಯನ್ನು ಬಿಡುವುದು; 13–18: ಪ್ರತಿ ಕರ್ಮದ ಐದು ಕಾರಣಗಳು; 19–40: ಜ್ಞಾನ, ಕರ್ಮ, ಕರ್ತ, ಬುದ್ಧಿ, ಧೃತಿ ಮತ್ತು ಸುಖ, ಪ್ರತಿಯೊಂದರಲ್ಲಿ ಮೂರು ಬಗೆ; 41–48: ಸ್ವಭಾವದಿಂದ ಹುಟ್ಟಿದ ಕರ್ತವ್ಯ, ಸ್ವಧರ್ಮವೇ ಶ್ರೇಷ್ಠ; 49–56: ಸಿದ್ಧಿಯಿಂದ ಬ್ರಹ್ಮದವರೆಗೆ; 57–65: ಈಶ್ವರ ಎಲ್ಲರ ಹೃದಯದಲ್ಲಿದ್ದಾನೆ; 66: "ಎಲ್ಲ ಧರ್ಮಗಳನ್ನೂ ಬಿಟ್ಟು ನನ್ನನ್ನು ಶರಣು ಹೊಂದು"; 67–72: ಈ ಉಪದೇಶವನ್ನು ಯಾರಿಗೆ ಹೇಳಬೇಕು; 73–78: ಅರ್ಜುನನ ಮೋಹ ದೂರವಾಗುತ್ತದೆ, ಸಂಜಯನ ಕೊನೆಯ ಮಾತು.',
)
T = {
1: 'ಅರ್ಜುನ ಹೇಳಿದನು: ಹೇ ಮಹಾಬಾಹು, ಹೇ ಹೃಷೀಕೇಶ, ಹೇ ಕೇಶಿನಿಷೂದನ, ಸಂನ್ಯಾಸ ಮತ್ತು ತ್ಯಾಗದ ತತ್ತ್ವವನ್ನು ಪ್ರತ್ಯೇಕವಾಗಿ ತಿಳಿಯಲು ಬಯಸುತ್ತೇನೆ.',
2: 'ಶ್ರೀಭಗವಂತ ಹೇಳಿದನು: ಕಾಮನೆಯಿಂದ ಮಾಡುವ ಕರ್ಮಗಳನ್ನು ಬಿಡುವುದನ್ನು ಜ್ಞಾನಿಗಳು ಸಂನ್ಯಾಸ ಎನ್ನುತ್ತಾರೆ. ಎಲ್ಲ ಕರ್ಮಗಳ ಫಲವನ್ನು ಬಿಡುವುದನ್ನು ವಿವೇಕಿಗಳು ತ್ಯಾಗ ಎನ್ನುತ್ತಾರೆ.',
3: 'ಕೆಲವು ಮನೀಷಿಗಳು ಕರ್ಮ ದೋಷದಿಂದ ಕೂಡಿದ್ದು, ಆದ್ದರಿಂದ ಬಿಡಬೇಕು ಎನ್ನುತ್ತಾರೆ. ಇನ್ನು ಕೆಲವರು ಯಜ್ಞ, ದಾನ ಮತ್ತು ತಪಸ್ಸಿನ ಕರ್ಮಗಳನ್ನು ಬಿಡಬಾರದು ಎನ್ನುತ್ತಾರೆ.',
4: 'ಹೇ ಭರತಶ್ರೇಷ್ಠ, ತ್ಯಾಗದ ಬಗ್ಗೆ ನನ್ನ ನಿರ್ಣಯವನ್ನು ಕೇಳು. ಹೇ ಪುರುಷವ್ಯಾಘ್ರ, ತ್ಯಾಗ ಮೂರು ಬಗೆ ಎಂದು ಹೇಳಲಾಗಿದೆ.',
5: 'ಯಜ್ಞ, ದಾನ ಮತ್ತು ತಪಸ್ಸಿನ ಕರ್ಮಗಳನ್ನು ಬಿಡಬಾರದು, ಅವನ್ನು ಮಾಡಲೇಬೇಕು. ಯಜ್ಞ, ದಾನ ಮತ್ತು ತಪಸ್ಸು ಜ್ಞಾನಿಗಳನ್ನು ಪವಿತ್ರಗೊಳಿಸುತ್ತವೆ.',
6: 'ಆದರೆ ಹೇ ಪಾರ್ಥ, ಈ ಕರ್ಮಗಳನ್ನೂ ಆಸಕ್ತಿ ಮತ್ತು ಫಲವನ್ನು ಬಿಟ್ಟು ಮಾಡಬೇಕು. ಇದು ನನ್ನ ನಿಶ್ಚಿತ ಮತ್ತು ಉತ್ತಮ ಅಭಿಪ್ರಾಯ.',
7: 'ನಿಯತ ಕರ್ಮವನ್ನು ಬಿಡುವುದು ಸರಿಯಲ್ಲ. ಮೋಹದಿಂದ ಅದನ್ನು ಬಿಡುವುದನ್ನು ತಾಮಸಿಕ ತ್ಯಾಗ ಎನ್ನುತ್ತಾರೆ.',
8: 'ಇದು ದುಃಖಕರ ಎಂದು, ದೈಹಿಕ ಕಷ್ಟದ ಭಯದಿಂದ ಕರ್ಮವನ್ನು ಬಿಡುವವನು ರಾಜಸಿಕ ತ್ಯಾಗ ಮಾಡುತ್ತಾನೆ; ಅವನಿಗೆ ತ್ಯಾಗದ ಫಲ ಸಿಗುವುದಿಲ್ಲ.',
9: 'ಹೇ ಅರ್ಜುನ, "ಇದನ್ನು ಮಾಡಲೇಬೇಕು" ಎಂದು ಆಸಕ್ತಿ ಮತ್ತು ಫಲವನ್ನು ಬಿಟ್ಟು ನಿಯತ ಕರ್ಮವನ್ನು ಮಾಡುವ ತ್ಯಾಗವನ್ನು ಸಾತ್ತ್ವಿಕ ಎಂದು ಭಾವಿಸಲಾಗಿದೆ.',
10: 'ಸತ್ತ್ವದಿಂದ ತುಂಬಿದ, ಬುದ್ಧಿವಂತ, ಸಂಶಯಗಳು ಹೋದ ತ್ಯಾಗಿ ಅಶುಭ ಕರ್ಮವನ್ನು ದ್ವೇಷಿಸುವುದಿಲ್ಲ, ಶುಭ ಕರ್ಮದಲ್ಲಿ ಆಸಕ್ತನಾಗುವುದಿಲ್ಲ.',
11: 'ದೇಹಧಾರಿಗೆ ಕರ್ಮಗಳನ್ನು ಸಂಪೂರ್ಣವಾಗಿ ಬಿಡುವುದು ಸಾಧ್ಯವಿಲ್ಲ. ಆದರೆ ಕರ್ಮಫಲವನ್ನು ಬಿಡುವವನನ್ನೇ ತ್ಯಾಗಿ ಎನ್ನುತ್ತಾರೆ.',
12: 'ಇಷ್ಟವಾದ, ಇಷ್ಟವಿಲ್ಲದ ಮತ್ತು ಮಿಶ್ರವಾದ ಎಂಬ ಮೂರು ಬಗೆಯ ಕರ್ಮಫಲ ತ್ಯಾಗ ಮಾಡದವರಿಗೆ ಸತ್ತ ನಂತರ ಸಿಗುತ್ತದೆ, ಆದರೆ ಸಂನ್ಯಾಸಿಗಳಿಗೆ ಎಂದಿಗೂ ಸಿಗುವುದಿಲ್ಲ.',
13: 'ಹೇ ಮಹಾಬಾಹು, ಎಲ್ಲ ಕರ್ಮಗಳ ಸಿದ್ಧಿಗಾಗಿ ಸಾಂಖ್ಯ ಸಿದ್ಧಾಂತದಲ್ಲಿ ಹೇಳಿದ ಈ ಐದು ಕಾರಣಗಳನ್ನು ನನ್ನಿಂದ ತಿಳಿ.',
14: 'ಅಧಿಷ್ಠಾನ (ದೇಹ), ಕರ್ತ, ಬಗೆಬಗೆಯ ಸಾಧನಗಳು (ಇಂದ್ರಿಯಗಳು), ಬಗೆಬಗೆಯ ಪ್ರಯತ್ನಗಳು, ಮತ್ತು ಐದನೆಯದು ದೈವ.',
15: 'ಮನುಷ್ಯ ದೇಹ, ಮಾತು ಮತ್ತು ಮನಸ್ಸಿನಿಂದ ಯಾವುದೇ ಕರ್ಮವನ್ನು ಆರಂಭಿಸಿದರೂ, ಅದು ನ್ಯಾಯವಾದುದಾಗಲಿ ಅನ್ಯಾಯವಾದುದಾಗಲಿ, ಅದಕ್ಕೆ ಈ ಐದೇ ಕಾರಣಗಳು.',
16: 'ಹೀಗಿರುವಾಗ, ಸಂಸ್ಕಾರವಿಲ್ಲದ ಬುದ್ಧಿಯಿಂದ ತನ್ನನ್ನೇ ಏಕೈಕ ಕರ್ತನೆಂದು ಕಾಣುವವನು ಮೂಢ, ಅವನು ನಿಜವಾಗಿ ಕಾಣುತ್ತಿಲ್ಲ.',
17: '"ನಾನು ಮಾಡುತ್ತಿದ್ದೇನೆ" ಎಂಬ ಭಾವವಿಲ್ಲದವನು, ಬುದ್ಧಿ ಅಂಟಿಕೊಳ್ಳದವನು ಈ ಎಲ್ಲ ಜನರನ್ನು ಕೊಂದರೂ ಕೊಂದಂತಲ್ಲ, ಬಂಧಿತನಾಗುವುದೂ ಇಲ್ಲ.',
18: 'ಜ್ಞಾನ, ತಿಳಿಯಬೇಕಾದುದು ಮತ್ತು ತಿಳಿಯುವವನು: ಈ ಮೂರೂ ಕರ್ಮದ ಪ್ರೇರಣೆ. ಸಾಧನ, ಕರ್ಮ ಮತ್ತು ಕರ್ತ: ಈ ಮೂರೂ ಕರ್ಮದ ಅಂಗಗಳು.',
19: 'ಗುಣ ಸಿದ್ಧಾಂತದಲ್ಲಿ ಜ್ಞಾನ, ಕರ್ಮ ಮತ್ತು ಕರ್ತ ಗುಣಗಳ ಭೇದದಂತೆ ಮೂರು ಬಗೆ ಎಂದು ಹೇಳಲಾಗಿದೆ. ಅವುಗಳನ್ನೂ ಸರಿಯಾಗಿ ಕೇಳು.',
20: 'ಯಾವುದರಿಂದ ಎಲ್ಲ ಜೀವಿಗಳಲ್ಲಿ, ವಿಭಾಗವಾದವುಗಳಲ್ಲಿ ವಿಭಾಗವಾಗದ, ಅವಿನಾಶಿಯಾದ ಒಂದೇ ಭಾವವನ್ನು ಕಾಣುತ್ತಾನೋ, ಆ ಜ್ಞಾನವನ್ನು ಸಾತ್ತ್ವಿಕ ಎಂದು ತಿಳಿ.',
21: 'ಎಲ್ಲ ಜೀವಿಗಳಲ್ಲಿ ಬೇರೆ ಬೇರೆ ಬಗೆಯ ಭಾವಗಳನ್ನು ಪ್ರತ್ಯೇಕವಾಗಿ ತಿಳಿಯುವ ಜ್ಞಾನವನ್ನು ರಾಜಸಿಕ ಎಂದು ತಿಳಿ.',
22: 'ಕಾರಣವಿಲ್ಲದೆ ಒಂದೇ ಕೆಲಸವನ್ನು ಸಮಸ್ತವೆಂದು ಭಾವಿಸಿ ಅದಕ್ಕೇ ಅಂಟಿಕೊಳ್ಳುವ, ತತ್ತ್ವವಿಲ್ಲದ, ಅಲ್ಪವಾದ ಜ್ಞಾನವನ್ನು ತಾಮಸಿಕ ಎನ್ನುತ್ತಾರೆ.',
23: 'ಫಲವನ್ನು ಬಯಸದವನು ಆಸಕ್ತಿಯಿಲ್ಲದೆ, ರಾಗದ್ವೇಷಗಳಿಲ್ಲದೆ ಮಾಡುವ ನಿಯತ ಕರ್ಮವನ್ನು ಸಾತ್ತ್ವಿಕ ಎನ್ನುತ್ತಾರೆ.',
24: 'ಆದರೆ ಕಾಮನೆಗಳನ್ನು ಬಯಸುವವನು ಅಹಂಕಾರದಿಂದ, ಬಹಳ ಶ್ರಮದಿಂದ ಮಾಡುವ ಕರ್ಮವನ್ನು ರಾಜಸಿಕ ಎನ್ನುತ್ತಾರೆ.',
25: 'ಪರಿಣಾಮ, ನಷ್ಟ, ಹಿಂಸೆ ಮತ್ತು ತನ್ನ ಸಾಮರ್ಥ್ಯವನ್ನು ನೋಡದೆ, ಮೋಹದಿಂದ ಆರಂಭಿಸುವ ಕರ್ಮವನ್ನು ತಾಮಸಿಕ ಎನ್ನುತ್ತಾರೆ.',
26: 'ಆಸಕ್ತಿಯಿಲ್ಲದ, "ನಾನು" ಎಂದು ಹೇಳಿಕೊಳ್ಳದ, ಧೈರ್ಯ ಮತ್ತು ಉತ್ಸಾಹದಿಂದ ಕೂಡಿದ, ಸಿದ್ಧಿ ಮತ್ತು ಅಸಿದ್ಧಿಗಳಲ್ಲಿ ಬದಲಾಗದ ಕರ್ತನನ್ನು ಸಾತ್ತ್ವಿಕ ಎನ್ನುತ್ತಾರೆ.',
27: 'ಆಸಕ್ತನಾದ, ಕರ್ಮಫಲವನ್ನು ಬಯಸುವ, ಲೋಭಿಯಾದ, ಹಿಂಸಾಸ್ವಭಾವದ, ಅಶುಚಿಯಾದ, ಹರ್ಷ ಶೋಕಗಳಿಗೆ ಒಳಗಾಗುವ ಕರ್ತನನ್ನು ರಾಜಸಿಕ ಎನ್ನುತ್ತಾರೆ.',
28: 'ಸಂಯಮವಿಲ್ಲದ, ಸಂಸ್ಕಾರವಿಲ್ಲದ, ಹಠಮಾರಿ, ಮೋಸಗಾರ, ಇತರರ ಜೀವನವನ್ನು ಹಾಳುಮಾಡುವ, ಸೋಮಾರಿ, ವಿಷಾದದಲ್ಲಿರುವ ಮತ್ತು ಮುಂದೂಡುವ ಕರ್ತನನ್ನು ತಾಮಸಿಕ ಎನ್ನುತ್ತಾರೆ.',
29: 'ಹೇ ಧನಂಜಯ, ಗುಣಗಳಂತೆ ಬುದ್ಧಿ ಮತ್ತು ಧೃತಿಯೂ ಮೂರು ಬಗೆ. ಅವುಗಳನ್ನು ಸಂಪೂರ್ಣವಾಗಿ, ಪ್ರತ್ಯೇಕವಾಗಿ ಹೇಳುತ್ತೇನೆ, ಕೇಳು.',
30: 'ಹೇ ಪಾರ್ಥ, ಪ್ರವೃತ್ತಿ ಮತ್ತು ನಿವೃತ್ತಿ, ಮಾಡಬೇಕಾದ್ದು ಮತ್ತು ಮಾಡಬಾರದ್ದು, ಭಯ ಮತ್ತು ಅಭಯ, ಬಂಧನ ಮತ್ತು ಮೋಕ್ಷವನ್ನು ತಿಳಿಯುವ ಬುದ್ಧಿ ಸಾತ್ತ್ವಿಕ.',
31: 'ಹೇ ಪಾರ್ಥ, ಧರ್ಮ ಮತ್ತು ಅಧರ್ಮ, ಮಾಡಬೇಕಾದ್ದು ಮತ್ತು ಮಾಡಬಾರದ್ದನ್ನು ಸರಿಯಾಗಿ ತಿಳಿಯಲಾಗದ ಬುದ್ಧಿ ರಾಜಸಿಕ.',
32: 'ಹೇ ಪಾರ್ಥ, ಕತ್ತಲೆಯಿಂದ ಮುಚ್ಚಿ ಅಧರ್ಮವನ್ನು ಧರ್ಮವೆಂದು ಭಾವಿಸುವ, ಎಲ್ಲ ವಿಷಯಗಳನ್ನೂ ತಲೆಕೆಳಗಾಗಿ ಕಾಣುವ ಬುದ್ಧಿ ತಾಮಸಿಕ.',
33: 'ಹೇ ಪಾರ್ಥ, ಅಚಲ ಯೋಗದಿಂದ ಮನಸ್ಸು, ಪ್ರಾಣ ಮತ್ತು ಇಂದ್ರಿಯಗಳ ಕಾರ್ಯಗಳನ್ನು ಹಿಡಿದಿಡುವ ಧೃತಿ ಸಾತ್ತ್ವಿಕ.',
34: 'ಆದರೆ ಹೇ ಪಾರ್ಥ, ಆಸಕ್ತಿಯಿಂದ ಫಲವನ್ನು ಬಯಸುತ್ತಾ ಧರ್ಮ, ಕಾಮ ಮತ್ತು ಅರ್ಥವನ್ನು ಹಿಡಿದಿಡುವ ಧೃತಿ ರಾಜಸಿಕ.',
35: 'ಹೇ ಪಾರ್ಥ, ಮೂಢನು ನಿದ್ರೆ, ಭಯ, ಶೋಕ, ವಿಷಾದ ಮತ್ತು ಮದವನ್ನು ಬಿಡದೆ ಹಿಡಿದಿಡುವ ಧೃತಿ ತಾಮಸಿಕ.',
36: 'ಹೇ ಭರತಶ್ರೇಷ್ಠ, ಈಗ ಮೂರು ಬಗೆಯ ಸುಖದ ಬಗ್ಗೆ ನನ್ನಿಂದ ಕೇಳು: ಅಭ್ಯಾಸದಿಂದ ಆನಂದ ಸಿಗುವ, ದುಃಖಕ್ಕೆ ಕೊನೆ ಹಾಡುವ ಸುಖ.',
37: 'ಆರಂಭದಲ್ಲಿ ವಿಷದಂತೆ, ಕೊನೆಯಲ್ಲಿ ಅಮೃತದಂತೆ ಇರುವ, ಆತ್ಮಬುದ್ಧಿಯ ಪ್ರಸನ್ನತೆಯಿಂದ ಹುಟ್ಟುವ ಸುಖವನ್ನು ಸಾತ್ತ್ವಿಕ ಎನ್ನುತ್ತಾರೆ.',
38: 'ಇಂದ್ರಿಯಗಳು ವಿಷಯಗಳೊಂದಿಗೆ ಸೇರುವುದರಿಂದ ಆರಂಭದಲ್ಲಿ ಅಮೃತದಂತೆ, ಕೊನೆಯಲ್ಲಿ ವಿಷದಂತೆ ಇರುವ ಸುಖವನ್ನು ರಾಜಸಿಕ ಎನ್ನುತ್ತಾರೆ.',
39: 'ಆರಂಭದಲ್ಲೂ ಕೊನೆಯಲ್ಲೂ ತನ್ನನ್ನು ಮೋಹಗೊಳಿಸುವ, ನಿದ್ರೆ, ಆಲಸ್ಯ ಮತ್ತು ಅಜಾಗರೂಕತೆಯಿಂದ ಹುಟ್ಟುವ ಸುಖವನ್ನು ತಾಮಸಿಕ ಎನ್ನುತ್ತಾರೆ.',
40: 'ಪ್ರಕೃತಿಯಿಂದ ಹುಟ್ಟಿದ ಈ ಮೂರು ಗುಣಗಳಿಂದ ಮುಕ್ತವಾದ ಯಾವ ಜೀವಿಯೂ ಭೂಮಿಯಲ್ಲಾಗಲಿ, ಸ್ವರ್ಗದಲ್ಲಿ ದೇವತೆಗಳಲ್ಲಾಗಲಿ ಇಲ್ಲ.',
41: 'ಹೇ ಪರಂತಪ, ಬ್ರಾಹ್ಮಣ, ಕ್ಷತ್ರಿಯ, ವೈಶ್ಯ ಮತ್ತು ಶೂದ್ರರ ಕರ್ಮಗಳು ಅವರ ಸ್ವಭಾವದಿಂದ ಹುಟ್ಟಿದ ಗುಣಗಳಂತೆ ವಿಭಾಗವಾಗಿವೆ.',
42: 'ಶಾಂತಿ, ಆತ್ಮಸಂಯಮ, ತಪಸ್ಸು, ಶುಚಿತ್ವ, ಕ್ಷಮೆ, ಸರಳತೆ, ಜ್ಞಾನ, ಅನುಭವದ ಜ್ಞಾನ ಮತ್ತು ಆಸ್ತಿಕತೆ: ಇವು ಸ್ವಭಾವದಿಂದ ಹುಟ್ಟಿದ ಬ್ರಾಹ್ಮಣ ಕರ್ಮಗಳು.',
43: 'ಶೌರ್ಯ, ತೇಜಸ್ಸು, ಧೈರ್ಯ, ಕೌಶಲ, ಯುದ್ಧದಲ್ಲಿ ಹಿಂಜರಿಯದಿರುವಿಕೆ, ದಾನ ಮತ್ತು ಆಡಳಿತ: ಇವು ಸ್ವಭಾವದಿಂದ ಹುಟ್ಟಿದ ಕ್ಷತ್ರಿಯ ಕರ್ಮಗಳು.',
44: 'ಕೃಷಿ, ಗೋರಕ್ಷಣೆ ಮತ್ತು ವ್ಯಾಪಾರ ಸ್ವಭಾವದಿಂದ ಹುಟ್ಟಿದ ವೈಶ್ಯ ಕರ್ಮಗಳು. ಸೇವಾರೂಪದ ಕರ್ಮ ಸ್ವಭಾವದಿಂದ ಹುಟ್ಟಿದ ಶೂದ್ರ ಕರ್ಮ.',
45: 'ತನ್ನ ತನ್ನ ಕರ್ಮದಲ್ಲಿ ತೊಡಗಿದ ಮನುಷ್ಯ ಸಿದ್ಧಿಯನ್ನು ಪಡೆಯುತ್ತಾನೆ. ತನ್ನ ಕರ್ಮದಲ್ಲಿ ತೊಡಗಿ ಸಿದ್ಧಿಯನ್ನು ಹೇಗೆ ಪಡೆಯುತ್ತಾನೆ ಎಂಬುದನ್ನು ಕೇಳು.',
46: 'ಯಾರಿಂದ ಜೀವಿಗಳು ನಡೆಯುತ್ತಿವೆಯೋ, ಯಾರಿಂದ ಇದೆಲ್ಲವೂ ವ್ಯಾಪಿಸಿದೆಯೋ, ಅವನನ್ನು ತನ್ನ ಕರ್ಮದಿಂದ ಪೂಜಿಸಿ ಮನುಷ್ಯ ಸಿದ್ಧಿಯನ್ನು ಪಡೆಯುತ್ತಾನೆ.',
47: 'ಚೆನ್ನಾಗಿ ಆಚರಿಸಿದ ಪರಧರ್ಮಕ್ಕಿಂತ ಗುಣವಿಲ್ಲದ ಸ್ವಧರ್ಮವೇ ಶ್ರೇಷ್ಠ. ಸ್ವಭಾವ ನಿಯಮಿಸಿದ ಕರ್ಮ ಮಾಡುವವನು ಪಾಪವನ್ನು ಪಡೆಯುವುದಿಲ್ಲ.',
48: 'ಹೇ ಕೌಂತೇಯ, ಸಹಜ ಕರ್ಮ ದೋಷದಿಂದ ಕೂಡಿದ್ದರೂ ಅದನ್ನು ಬಿಡಬಾರದು. ಹೊಗೆಯಿಂದ ಬೆಂಕಿ ಮುಚ್ಚಿರುವಂತೆ, ಎಲ್ಲ ಆರಂಭಗಳೂ ದೋಷದಿಂದ ಮುಚ್ಚಿರುತ್ತವೆ.',
49: 'ಎಲ್ಲೆಡೆ ಆಸಕ್ತಿಯಿಲ್ಲದ ಬುದ್ಧಿಯುಳ್ಳವನು, ತನ್ನನ್ನು ಗೆದ್ದವನು, ಕಾಮನೆಗಳು ಹೋದವನು ಸಂನ್ಯಾಸದ ಮೂಲಕ ನೈಷ್ಕರ್ಮ್ಯ (ಕರ್ಮಬಂಧನವಿಲ್ಲದ) ಎಂಬ ಪರಮ ಸಿದ್ಧಿಯನ್ನು ಪಡೆಯುತ್ತಾನೆ.',
50: 'ಹೇ ಕೌಂತೇಯ, ಸಿದ್ಧಿಯನ್ನು ಪಡೆದವನು ಜ್ಞಾನದ ಪರಮ ನಿಷ್ಠೆಯಾದ ಬ್ರಹ್ಮವನ್ನು ಹೇಗೆ ಸೇರುತ್ತಾನೆ ಎಂಬುದನ್ನು ನನ್ನಿಂದ ಸಂಕ್ಷೇಪವಾಗಿ ತಿಳಿ.',
51: 'ಶುದ್ಧವಾದ ಬುದ್ಧಿಯಿಂದ ಕೂಡಿ, ಧೃತಿಯಿಂದ ಮನಸ್ಸನ್ನು ನಿಗ್ರಹಿಸಿ, ಶಬ್ದ ಮುಂತಾದ ವಿಷಯಗಳನ್ನು ಬಿಟ್ಟು, ರಾಗದ್ವೇಷಗಳನ್ನು ತೊರೆದು,',
52: 'ಏಕಾಂತದಲ್ಲಿ ವಾಸಿಸುತ್ತಾ, ಮಿತವಾಗಿ ತಿನ್ನುತ್ತಾ, ಮಾತು, ದೇಹ ಮತ್ತು ಮನಸ್ಸನ್ನು ನಿಗ್ರಹಿಸಿ, ಸದಾ ಧ್ಯಾನಯೋಗದಲ್ಲಿ ತೊಡಗಿ, ವೈರಾಗ್ಯವನ್ನು ಆಶ್ರಯಿಸಿ,',
53: 'ಅಹಂಕಾರ, ಬಲ, ದರ್ಪ, ಕಾಮ, ಕ್ರೋಧ ಮತ್ತು ಸಂಗ್ರಹವನ್ನು ಬಿಟ್ಟು, "ನನ್ನದು" ಎಂಬ ಭಾವವಿಲ್ಲದೆ, ಶಾಂತನಾದವನು ಬ್ರಹ್ಮಭಾವಕ್ಕೆ ಅರ್ಹನಾಗುತ್ತಾನೆ.',
54: 'ಬ್ರಹ್ಮಭಾವವನ್ನು ಪಡೆದು, ಪ್ರಸನ್ನ ಮನಸ್ಸಿನಿಂದ ಅವನು ದುಃಖಿಸುವುದಿಲ್ಲ, ಬಯಸುವುದಿಲ್ಲ. ಎಲ್ಲ ಜೀವಿಗಳಲ್ಲಿ ಸಮನಾಗಿದ್ದು, ನನ್ನಲ್ಲಿ ಪರಮ ಭಕ್ತಿಯನ್ನು ಪಡೆಯುತ್ತಾನೆ.',
55: 'ಭಕ್ತಿಯಿಂದ ನಾನು ಎಷ್ಟು ಮತ್ತು ಯಾರು ಎಂಬುದನ್ನು ತತ್ತ್ವವಾಗಿ ತಿಳಿಯುತ್ತಾನೆ. ನನ್ನನ್ನು ತತ್ತ್ವವಾಗಿ ತಿಳಿದ ನಂತರ ತಕ್ಷಣವೇ ನನ್ನಲ್ಲಿ ಪ್ರವೇಶಿಸುತ್ತಾನೆ.',
56: 'ಸದಾ ಎಲ್ಲ ಕರ್ಮಗಳನ್ನೂ ಮಾಡುತ್ತಿದ್ದರೂ, ನನ್ನ ಆಶ್ರಯ ಪಡೆದವನು ನನ್ನ ಅನುಗ್ರಹದಿಂದ ಶಾಶ್ವತವಾದ, ಅವಿನಾಶಿ ಪದವನ್ನು ಪಡೆಯುತ್ತಾನೆ.',
57: 'ಮನಸ್ಸಿನಿಂದ ಎಲ್ಲ ಕರ್ಮಗಳನ್ನೂ ನನಗೆ ಅರ್ಪಿಸಿ, ನನ್ನನ್ನೇ ಪರಮ ಗುರಿಯಾಗಿ ಭಾವಿಸಿ, ಬುದ್ಧಿಯೋಗವನ್ನು ಆಶ್ರಯಿಸಿ, ಸದಾ ನನ್ನಲ್ಲಿ ಮನಸ್ಸಿಡು.',
58: 'ನನ್ನಲ್ಲಿ ಮನಸ್ಸಿಟ್ಟರೆ ನನ್ನ ಅನುಗ್ರಹದಿಂದ ಎಲ್ಲ ಕಷ್ಟಗಳನ್ನೂ ದಾಟುತ್ತೀಯ. ಆದರೆ ಅಹಂಕಾರದಿಂದ ನನ್ನ ಮಾತು ಕೇಳದಿದ್ದರೆ ನಾಶವಾಗುತ್ತೀಯ.',
59: 'ಅಹಂಕಾರವನ್ನು ಆಶ್ರಯಿಸಿ "ನಾನು ಯುದ್ಧ ಮಾಡುವುದಿಲ್ಲ" ಎಂದು ನೀನು ಭಾವಿಸಿದರೆ, ನಿನ್ನ ಆ ನಿಶ್ಚಯ ವ್ಯರ್ಥ; ನಿನ್ನ ಸ್ವಭಾವವೇ ನಿನ್ನನ್ನು ಅದರಲ್ಲಿ ತೊಡಗಿಸುತ್ತದೆ.',
60: 'ಹೇ ಕೌಂತೇಯ, ನಿನ್ನ ಸ್ವಭಾವದಿಂದ ಹುಟ್ಟಿದ ನಿನ್ನ ಕರ್ಮದಿಂದ ಬಂಧಿತನಾಗಿ, ಮೋಹದಿಂದ ಮಾಡಬಾರದೆಂದು ಬಯಸುತ್ತಿರುವುದನ್ನು ನೀನು ಅಸಹಾಯಕನಾಗಿಯಾದರೂ ಮಾಡುತ್ತೀಯ.',
61: 'ಹೇ ಅರ್ಜುನ, ಈಶ್ವರ ಎಲ್ಲ ಜೀವಿಗಳ ಹೃದಯದಲ್ಲಿದ್ದಾನೆ. ಯಂತ್ರದ ಮೇಲೆ ಏರಿಸಿದಂತೆ ಎಲ್ಲ ಜೀವಿಗಳನ್ನೂ ತನ್ನ ಮಾಯೆಯಿಂದ ತಿರುಗಿಸುತ್ತಿದ್ದಾನೆ.',
62: 'ಹೇ ಭಾರತ, ಪೂರ್ಣ ಭಾವದಿಂದ ಅವನನ್ನೇ ಶರಣು ಹೋಗು. ಅವನ ಅನುಗ್ರಹದಿಂದ ಪರಮ ಶಾಂತಿಯನ್ನೂ ಶಾಶ್ವತ ಸ್ಥಾನವನ್ನೂ ಪಡೆಯುತ್ತೀಯ.',
63: 'ರಹಸ್ಯಗಳಿಗಿಂತ ರಹಸ್ಯವಾದ ಈ ಜ್ಞಾನವನ್ನು ನಿನಗೆ ಹೇಳಿದ್ದೇನೆ. ಇದನ್ನು ಸಂಪೂರ್ಣವಾಗಿ ಆಲೋಚಿಸಿ, ನಿನಗೆ ಇಷ್ಟಬಂದಂತೆ ಮಾಡು.',
64: 'ಎಲ್ಲಕ್ಕಿಂತ ರಹಸ್ಯವಾದ ನನ್ನ ಪರಮ ವಚನವನ್ನು ಮತ್ತೆ ಕೇಳು. ನೀನು ನನಗೆ ಅತ್ಯಂತ ಪ್ರಿಯ, ಆದ್ದರಿಂದ ನಿನ್ನ ಹಿತಕ್ಕಾಗಿ ಹೇಳುತ್ತೇನೆ.',
65: 'ನನ್ನಲ್ಲಿ ಮನಸ್ಸಿಡು, ನನ್ನ ಭಕ್ತನಾಗು, ನನ್ನನ್ನು ಪೂಜಿಸು, ನನಗೆ ನಮಸ್ಕರಿಸು. ನೀನು ನನ್ನನ್ನೇ ಸೇರುತ್ತೀಯ; ಇದನ್ನು ನಿನಗೆ ಸತ್ಯವಾಗಿ ಪ್ರತಿಜ್ಞೆ ಮಾಡುತ್ತೇನೆ, ಏಕೆಂದರೆ ನೀನು ನನಗೆ ಪ್ರಿಯ.',
67: 'ಇದನ್ನು ತಪಸ್ಸಿಲ್ಲದವನಿಗೆ, ಭಕ್ತಿಯಿಲ್ಲದವನಿಗೆ, ಕೇಳಲು ಇಷ್ಟವಿಲ್ಲದವನಿಗೆ, ನನ್ನ ಮೇಲೆ ಅಸೂಯೆಪಡುವವನಿಗೆ ಎಂದಿಗೂ ಹೇಳಬಾರದು.',
68: 'ಈ ಪರಮ ರಹಸ್ಯವನ್ನು ನನ್ನ ಭಕ್ತರಿಗೆ ಹೇಳುವವನು, ನನ್ನಲ್ಲಿ ಪರಮ ಭಕ್ತಿಯನ್ನು ತೋರಿ, ಸಂಶಯವಿಲ್ಲದೆ ನನ್ನನ್ನೇ ಸೇರುತ್ತಾನೆ.',
69: 'ಮನುಷ್ಯರಲ್ಲಿ ಅವನಿಗಿಂತ ನನಗೆ ಪ್ರಿಯವಾದ ಕೆಲಸ ಮಾಡುವವನು ಬೇರೊಬ್ಬನಿಲ್ಲ. ಭೂಮಿಯ ಮೇಲೆ ಅವನಿಗಿಂತ ನನಗೆ ಪ್ರಿಯನಾದವನು ಬೇರೊಬ್ಬನಿರುವುದಿಲ್ಲ.',
70: 'ನಮ್ಮ ಈ ಧರ್ಮಸಂವಾದವನ್ನು ಅಧ್ಯಯನ ಮಾಡುವವನು ಜ್ಞಾನಯಜ್ಞದಿಂದ ನನ್ನನ್ನು ಪೂಜಿಸಿದಂತೆ ಎಂದು ನನ್ನ ಅಭಿಪ್ರಾಯ.',
71: 'ಶ್ರದ್ಧೆಯಿಂದ, ಅಸೂಯೆಯಿಲ್ಲದೆ ಇದನ್ನು ಕೇಳುವವನೂ ಮುಕ್ತನಾಗಿ, ಪುಣ್ಯಕರ್ಮ ಮಾಡುವವರ ಶುಭ ಲೋಕಗಳನ್ನು ಸೇರುತ್ತಾನೆ.',
72: 'ಹೇ ಪಾರ್ಥ, ನೀನು ಇದನ್ನು ಏಕಾಗ್ರ ಮನಸ್ಸಿನಿಂದ ಕೇಳಿದೆಯಾ? ಹೇ ಧನಂಜಯ, ಅಜ್ಞಾನದಿಂದ ಹುಟ್ಟಿದ ನಿನ್ನ ಮೋಹ ನಾಶವಾಯಿತೇ?',
73: 'ಅರ್ಜುನ ಹೇಳಿದನು: ಹೇ ಅಚ್ಯುತ, ನಿಮ್ಮ ಅನುಗ್ರಹದಿಂದ ನನ್ನ ಮೋಹ ನಾಶವಾಯಿತು, ನನಗೆ ಸ್ಮೃತಿ ಮರಳಿ ಬಂದಿತು. ಸಂಶಯಗಳು ಹೋಗಿ ನಾನು ಸ್ಥಿರನಾಗಿದ್ದೇನೆ. ನಿಮ್ಮ ಮಾತಿನಂತೆ ಮಾಡುತ್ತೇನೆ.',
74: 'ಸಂಜಯ ಹೇಳಿದನು: ಹೀಗೆ ವಾಸುದೇವ ಮತ್ತು ಮಹಾತ್ಮನಾದ ಪಾರ್ಥನ ನಡುವೆ ನಡೆದ, ರೋಮಾಂಚನ ಉಂಟುಮಾಡುವ ಈ ಅದ್ಭುತ ಸಂವಾದವನ್ನು ನಾನು ಕೇಳಿದೆ.',
75: 'ವ್ಯಾಸರ ಅನುಗ್ರಹದಿಂದ ಈ ಪರಮ ರಹಸ್ಯವಾದ ಯೋಗವನ್ನು, ಯೋಗೇಶ್ವರನಾದ ಶ್ರೀಕೃಷ್ಣನೇ ಸ್ವತಃ ಹೇಳುತ್ತಿರುವಾಗ ನೇರವಾಗಿ ಕೇಳಿದೆ.',
76: 'ಹೇ ರಾಜನೇ, ಶ್ರೀಕೃಷ್ಣ ಮತ್ತು ಅರ್ಜುನರ ನಡುವಿನ ಈ ಪವಿತ್ರ, ಅದ್ಭುತ ಸಂವಾದವನ್ನು ಮತ್ತೆ ಮತ್ತೆ ನೆನೆದು ಕ್ಷಣಕ್ಷಣಕ್ಕೂ ಆನಂದಿಸುತ್ತಿದ್ದೇನೆ.',
77: 'ಹೇ ರಾಜನೇ, ಶ್ರೀಹರಿಯ ಆ ಅತ್ಯಂತ ಅದ್ಭುತ ರೂಪವನ್ನು ಮತ್ತೆ ಮತ್ತೆ ನೆನೆದು ನನಗೆ ಮಹಾ ಆಶ್ಚರ್ಯವಾಗುತ್ತಿದೆ, ಮತ್ತೆ ಮತ್ತೆ ಆನಂದಿಸುತ್ತಿದ್ದೇನೆ.',
}
